  "decode.kind.family.title": "Keluarga model",
  "decode.kind.family.desc": "Lini model dasar — sering kali dengan nomor versinya terlampir.",
  "decode.kind.version.title": "Versi",
  "decode.kind.version.desc": "Generasi / versi rilis dari keluarga model tersebut.",
  "decode.kind.params.title": "Jumlah parameter",
  "decode.kind.params.desc": "Total parameter (miliar). Menentukan kualitas dan VRAM — lebih besar = lebih mampu tetapi lebih berat.",
  "decode.kind.paramsM.title": "Jumlah parameter (M)",
  "decode.kind.paramsM.desc": "Jutaan parameter — model kecil / cocok untuk perangkat edge.",
  "decode.kind.moe.title": "Mixture of Experts (MoE)",
  "decode.kind.moe.desc": "jumlah ahli × ukuran masing-masing (mis. 8x7B). Hanya beberapa ahli yang berjalan per token (komputasi cepat), tetapi SEMUA ahli harus muat di VRAM.",
  "decode.kind.moeActive.title": "MoE — parameter aktif",
  "decode.kind.moeActive.desc": "Parameter aktif per token (mis. A3B = 3B aktif). Komputasi ≈ parameter aktif; VRAM ≈ total parameter.",
  "decode.kind.quantAWQ.title": "Kuantisasi · AWQ",
  "decode.kind.quantAWQ.desc": "Activation-aware Weight Quantization (~4-bit). ~4× lebih kecil, cepat di GPU, akurasi sedikit menurun.",
  "decode.kind.quantGPTQ.title": "Kuantisasi · GPTQ",
  "decode.kind.quantGPTQ.desc": "Kuantisasi bobot 4-bit GPTQ. Kecil & cepat di GPU; akurasi sedikit menurun.",
  "decode.kind.quantGGUF.title": "Format · GGUF",
  "decode.kind.quantGGUF.desc": "Format llama.cpp — berjalan di CPU dan GPU dengan banyak tingkat kuantisasi (Q4…Q8). Sangat cocok untuk penggunaan lokal / Mac.",
  "decode.kind.quantFP8.title": "Kuantisasi · FP8",
  "decode.kind.quantFP8.desc": "Floating point 8-bit. ~2× lebih kecil dari BF16, hampir tanpa kehilangan kualitas, cepat di GPU modern (Hopper/Blackwell/MI300).",
  "decode.kind.quantNVFP4.title": "Kuantisasi · NVFP4 / MXFP4",
  "decode.kind.quantNVFP4.desc": "Float 4-bit (NVFP4 di Blackwell, MXFP4 mis. di gpt-oss). ~4× lebih kecil dengan akurasi lebih baik daripada INT4.",
  "decode.kind.quantINT.title": "Kuantisasi · INT4/INT8",
  "decode.kind.quantINT.desc": "Kuantisasi integer (4 atau 8-bit). Lebih kecil & lebih cepat; INT4 mengorbankan sebagian akurasi.",
  "decode.kind.quantWA.title": "Kuantisasi · bit W/A",
  "decode.kind.quantWA.desc": "Lebar bit untuk Bobot (W) dan Aktivasi (A) — mis. W4A16 = bobot 4-bit, aktivasi 16-bit.",
  "decode.kind.quantBnb.title": "Kuantisasi · bitsandbytes",
  "decode.kind.quantBnb.desc": "4-bit / 8-bit secara on-the-fly (bitsandbytes). Mudah dimuat, bagus untuk VRAM terbatas.",
  "decode.kind.quantDynamic.title": "Kuantisasi · dinamis",
  "decode.kind.quantDynamic.desc": "Kuantisasi dinamis — skala dihitung saat runtime (sering dipasangkan dengan FP8).",
  "decode.kind.precision.title": "Presisi",
  "decode.kind.precision.desc": "Presisi bobot asli (BF16/FP16 = 2 byte, FP32 = 4). Kualitas penuh, ukuran terbesar.",
  "decode.kind.instruct.title": "Instruction-tuned",
  "decode.kind.instruct.desc": "Di-fine-tune untuk mengikuti instruksi / chat. Gunakan ini untuk asisten dan sebagian besar tugas.",
  "decode.kind.chat.title": "Di-tune untuk chat",
