  "decode.kind.base.desc": "Hanya melalui pra-pelatihan — BUKAN instruction-tuned. Untuk fine-tuning, bukan untuk langsung dipakai chat.",
  "decode.kind.coder.title": "Khusus kode",
  "decode.kind.coder.desc": "Di-tune untuk pemrograman / pembuatan kode.",
