  "decode.kind.embedding.title": "Embedding",
  "decode.kind.embedding.desc": "Menghasilkan vektor untuk pencarian / RAG — bukan model chat.",
  "decode.kind.reranker.title": "Reranker",
  "decode.kind.reranker.desc": "Memberi skor / mengurutkan dokumen untuk pencarian — bukan model generatif.",
  "decode.kind.reasoning.title": "Penalaran",
  "decode.kind.reasoning.desc": "Model penalaran / 'berpikir' (R1, QwQ, distill…) — kuat untuk masalah multi-langkah.",
  "decode.kind.sizeClass.title": "Kelas ukuran",
  "decode.kind.sizeClass.desc": "Tingkat ukuran relatif (mini / small / large …).",
  "decode.kind.speed.title": "Dioptimalkan untuk kecepatan",
  "decode.kind.speed.desc": "Di-tune untuk latensi rendah / throughput (turbo / flash / lite).",
