  "decode.kind.context.desc": "Jendela konteks maksimum yang ditargetkan varian ini (mis. 128k token).",
  "decode.kind.date.title": "Snapshot rilis",
  "decode.kind.date.desc": "Kode tanggal rilis / pelatihan (mis. 2507 ≈ 2025-07).",
  "decode.kind.format.title": "Format",
  "decode.kind.format.desc": "Format pengemasan / runtime (HF Transformers, MLX, ONNX …).",
  "decode.kind.agentic.title": "Agentic / penggunaan tool",
  "decode.kind.agentic.desc": "Di-tune untuk alur kerja agen dan pemanggilan tool / fungsi.",
